import{_ as n,o as l,c as e,ag as p}from"./chunks/framework.PVHj0As1.js";const t="/pub-blog/assets/image-20240902230122815.DumBn54v.png",h="/pub-blog/assets/image-20240902231634937.C5n-hMXD.png",i="/pub-blog/assets/PixPin_2024-09-09_20-54-27.B6sFzXer.gif",k="/pub-blog/assets/image-20240909210811015.D6xKf6Dd.png",a="/pub-blog/assets/output-1725888739673.BmZfRQzB.png",r="/pub-blog/assets/image-20240909211939272.BHuUbKgE.png",E="/pub-blog/assets/image-20240909211939272.BHuUbKgE.png",d="/pub-blog/assets/output.Bq7iJEfT.png",g="/pub-blog/assets/image-20240909214010076.DIz1hJ97.png",c="/pub-blog/assets/image-20240909214836639.C3YdAE82.png",y="/pub-blog/assets/image-20240909214913820.CtJXTPZ6.png",o="/pub-blog/assets/image-20240909215957894.DQ4Fy2oL.png",u="/pub-blog/assets/image-20240909220252656.DQ7IjyfX.png",b="/pub-blog/assets/image-20240909220457099.LiDZ5yGe.png",F="/pub-blog/assets/PixPin_2024-09-09_22-04-01.CrjSR-N6.gif",m="/pub-blog/assets/image-20240909222855321.BUmE-jhn.png",A="/pub-blog/assets/PixPin_2024-09-09_22-36-51.CtwEVh0W.gif",D="/pub-blog/assets/image-20240909224315034.GPmsEO5m.png",C="/pub-blog/assets/output-1725893267840.wB76wghu.png",B="/pub-blog/assets/image-20240909230235647.P_UNku6Q.png",f="/pub-blog/assets/image-20240909225939158.Bv024tqH.png",x="/pub-blog/assets/output-1725894264657.BS1260VN.png",R="/pub-blog/assets/image-20240909232140090.BPeILRyl.png",v="/pub-blog/assets/PixPin_2024-09-09_23-56-16.CQYkMyHu.gif",q="/pub-blog/assets/image-20240909234345836.DdQUJ3l0.png",P="/pub-blog/assets/image-20240909234518121.BMzcMqpS.png",_="/pub-blog/assets/image-20240909234304591.DA5aNTz0.png",M="/pub-blog/assets/image-20240909234703000.WgBlglYU.png",S="/pub-blog/assets/image-20240909235517058.GhKIkznz.png",I="/pub-blog/assets/PixPin_2024-09-10_00-00-11.PKjRyv9a.gif",T="/pub-blog/assets/image-20240909235855966.D5KYrU9k.png",$=JSON.parse('{"title":"带你实现HarmonyOS Next 微信聊天02","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 微信聊天/带你实现HarmonyOS Next 微信聊天02/带你实现HarmonyOS Next 微信聊天02.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 微信聊天/带你实现HarmonyOS Next 微信聊天02/带你实现HarmonyOS Next 微信聊天02.md","lastUpdated":1730788610000,"__rawMarkdown":"# 带你实现HarmonyOS Next 微信聊天02\\n\\n> 接上一篇\\n\\n## 前言\\n\\n代码会统一放在码云上\\n\\n## 案例目标\\n\\n> 这个是安卓手机上的真正的微信聊天界面功能效果\\n\\n![image-20240902230122815](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240902230122815.png)\\n\\n## 实际效果\\n\\n![image-20240902231634937](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240902231634937.png)\\n\\n## 案例功能\\n\\n**上一篇，已经实现了以下功能**\\n\\n- [x] 页面沉浸式\\n- [x] 聊天内容滚动\\n- [x] 输入框状态切换\\n- [x] 聊天信息框宽度自适应\\n- [x] 输入法避让\\n- [x] canvas声纹 按住说话 \\n- [x] 发送文字\\n- [ ] 录音-发送语音\\n- [ ] 语音消息根据时长自动宽度\\n- [ ] 手势坐标检测取消发送-语音转文字 \\n- [ ] 声音播放-语音消息\\n- [ ] AI 语音转文字\\n\\n\\n\\n## 发送声音-功能演示\\n\\n![PixPin_2024-09-09_20-54-27](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/PixPin_2024-09-09_20-54-27.gif)\\n\\n\\n\\n## 发送声音主要流程\\n\\n![image-20240909210811015](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909210811015.png)\\n\\n---\\n\\n## 发送声音结合UI交互-主要流程\\n\\n![output](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/output-1725888739673.png)\\n\\n## 声明麦克风权限\\n\\n![image-20240909211939272](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909211939272.png)\\n\\n应用需要在module.json5配置文件的[requestPermissions](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/module-configuration-file-V5#requestpermissions标签)标签中声明权限。\\n\\n| 属性名称  | 含义                                                         | 是否可缺省                                                   |\\n| --------- | ------------------------------------------------------------ | ------------------------------------------------------------ |\\n| name      | 标识需要使用的权限名称。取值范围请参考[应用权限列表](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/permissions-for-all-V5)。 | 该标签不可缺省，且必须为系统定义权限或[definePermissions](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/module-configuration-file-V5#definepermissions标签)中定义的权限。 |\\n| reason    | 标识申请权限的原因，取值需要采用资源引用格式，以适配多语种。 | **说明：**当申请的权限为user_grant权限时，该字段必填，否则不允许在应用市场上架。 |\\n| usedScene | 标识权限使用的场景，包含abilities和when两个子标签。- - when：表示调用时机，支持的取值包括inuse（使用时）和always（始终）。 | 当申请的权限为user_grant权限时，abilities标签在hap中必填，when标签可选。 |\\n\\n`\\\\entry\\\\src\\\\main\\\\module.json5`\\n\\n**requestPermissions**\\n\\n```TypeScript\\n{\\n  \\"module\\": {\\n    ...\\n    \\"requestPermissions\\": [\\n      {\\n        \\"name\\": \\"ohos.permission.MICROPHONE\\",\\n        \\"reason\\": \\"$string:voice_reason\\",\\n        \\"usedScene\\": {\\n          \\"abilities\\": [\\n            \\"FormAbility\\"\\n          ],\\n          \\"when\\": \\"always\\"\\n        }\\n      }\\n    ],\\n  }\\n}\\n```\\n\\n`\\\\entry\\\\src\\\\main\\\\resources\\\\base\\\\element\\\\string.json `  \\n\\n**$string:voice_reason\\"**\\n\\n```TypeScript\\n{\\n  \\"string\\": [\\n    {\\n      \\"name\\": \\"module_desc\\",\\n      \\"value\\": \\"module description\\"\\n    },\\n    {\\n      \\"name\\": \\"EntryAbility_desc\\",\\n      \\"value\\": \\"description\\"\\n    },\\n    {\\n      \\"name\\": \\"EntryAbility_label\\",\\n      \\"value\\": \\"label\\"\\n    },\\n    {\\n      \\"name\\": \\"voice_reason\\",\\n      \\"value\\": \\"用于获取用户的录音\\"\\n    }\\n  ]\\n}\\n```\\n\\n## 封装申请权限的工具类 \\n\\n权限工具类的主要功能为：\\n\\n1. 检测是否已经申请相关权限\\n2. 申请相关权限\\n\\n\\n\\n步骤：\\n\\n1. 新建文件 `\\\\entry\\\\src\\\\main\\\\ets\\\\utils\\\\permissionMananger.ets`\\n\\n2. 实现以下代码\\n\\n   ```typescript\\n   // 导入必要的模块，包括权限管理相关的功能\\n   import { abilityAccessCtrl, bundleManager, common, Permissions } from \'@kit.AbilityKit\';\\n   \\n   export class PermissionManager {\\n     // 静态方法用于检查给定的权限是否已经被授予\\n     static checkPermission(permissions: Permissions[]): boolean {\\n       // 创建一个访问令牌管理器实例\\n       let atManager: abilityAccessCtrl.AtManager = abilityAccessCtrl.createAtManager();\\n       // 初始化tokenID为0，稍后将获取真实的tokenID\\n       let tokenID: number = 0;\\n   \\n       // 获取本应用的包信息\\n       const bundleInfo =\\n         bundleManager.getBundleInfoForSelfSync(bundleManager.BundleFlag.GET_BUNDLE_INFO_WITH_APPLICATION);\\n   \\n       // 设置tokenID为应用的访问令牌ID\\n       tokenID = bundleInfo.appInfo.accessTokenId;\\n   \\n       // 如果没有传入任何权限，则返回false表示没有权限\\n       if (permissions.length === 0) {\\n         return false;\\n       } else {\\n         // 检查所有请求的权限是否都被授予\\n         return permissions.every(permission =>\\n         abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED ===\\n         atManager.checkAccessTokenSync(tokenID, permission)\\n         );\\n       }\\n     }\\n   \\n     // 异步静态方法用于请求用户授权指定的权限\\n     static async requestPermission(permissions: Permissions[]): Promise<boolean> {\\n       // 创建一个访问令牌管理器实例\\n       let atManager: abilityAccessCtrl.AtManager = abilityAccessCtrl.createAtManager();\\n   \\n       // 获取上下文（这里假设getContext是一个可以获取到UI能力上下文的方法）\\n       let context: Context = getContext() as common.UIAbilityContext;\\n   \\n       // 请求用户授权指定的权限\\n       const result = await atManager.requestPermissionsFromUser(context, permissions);\\n   \\n       // 检查请求结果是否成功（authResults数组中每个元素都应该是0，表示成功）\\n       return !!result.authResults.length && result.authResults.every(authResults => authResults === 0);\\n     }\\n   }\\n   ```\\n\\n3. 首页中  **aboutToAppear** 中调用\\n\\n   ```typescript\\n   // 页面开始显示触发\\n   async aboutToAppear() {\\n     // 1 检查是否有权限\\n     // 2 如果没有权限 再去申请权限\\n     const permissionList: Permissions[] = [\\"ohos.permission.MICROPHONE\\"]\\n     const result = await PermissionManager.checkPermission(permissionList)\\n     if (!result) {\\n       PermissionManager.requestPermission(permissionList)\\n     }\\n   }\\n   ```\\n\\n4. 最后效果\\n\\n   ![image-20240909212046512](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909212046512.png)\\n\\n\\n\\n\\n\\n\\n\\n## 声音录制 AudioCapturer\\n\\n[AudioCapturer](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/using-audiocapturer-for-recording-0000001774120322)是音频采集器，用于录制PCM（Pulse Code Modulation）音频数据\\n\\n![output](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/output.png)\\n\\n## 封装录制声音类\\n\\n根据上图的AudioCapturer使用流程，我们将封装 AudioCapturer录音类，主要有三个核心方法：\\n\\n1. 创建 AudioCapturer实例\\n2. 开始录音\\n3. 停止录音\\n\\n\\n\\n`\\\\entry\\\\src\\\\main\\\\ets\\\\utils\\\\AudioCapturerManager.ets`\\n\\n```typescript\\n// 导入音频处理模块\\nimport { audio } from \'@kit.AudioKit\';\\n// 导入文件系统模块\\nimport fs from \'@ohos.file.fs\';\\n\\n// 定义一个接口来描述录音文件的信息\\nexport interface RecordFile {\\n  recordFilePath: string, // 录音文件的路径\\n  startRecordTime: number, // 开始录音的时间戳\\n  endRecordTime: number // 结束录音的时间戳\\n}\\n\\n// 定义一个管理音频录制的类\\nexport class AudioCapturerManager {\\n  // 静态属性，用于存储当前的音频捕获器实例\\n  static audioCapturer: audio.AudioCapturer | null = null;\\n  // 静态私有属性，用于存储录音文件的路径\\n  private static recordFilePath: string = \\"\\";\\n  // 静态私有属性，用于存储开始录音的时间戳\\n  private static startRecordTime: number = 0;\\n  // 静态私有属性，用于存储结束录音的时间戳\\n  private static endRecordTime: number = 0;\\n\\n  // 静态异步方法，用于创建音频捕获器实例\\n  static async createAudioCapturer() {\\n    if (AudioCapturerManager.audioCapturer) {\\n      return AudioCapturerManager.audioCapturer\\n    }\\n    // 设置音频流信息配置\\n    let audioStreamInfo: audio.AudioStreamInfo = {\\n      samplingRate: audio.AudioSamplingRate.SAMPLE_RATE_16000, // 设置采样率为16kHz\\n      channels: audio.AudioChannel.CHANNEL_1, // 设置单声道\\n      sampleFormat: audio.AudioSampleFormat.SAMPLE_FORMAT_S16LE, // 设置样本格式为16位小端\\n      encodingType: audio.AudioEncodingType.ENCODING_TYPE_RAW // 设置编码类型为原始数据\\n    };\\n\\n    // 设置音频捕获信息配置\\n    let audioCapturerInfo: audio.AudioCapturerInfo = {\\n      source: audio.SourceType.SOURCE_TYPE_MIC, // 设置麦克风为音频来源\\n      capturerFlags: 0 // 捕获器标志，此处为默认值\\n    };\\n\\n    // 创建音频捕获选项对象\\n    let audioCapturerOptions: audio.AudioCapturerOptions = {\\n      streamInfo: audioStreamInfo, // 使用上面定义的音频流信息\\n      capturerInfo: audioCapturerInfo // 使用上面定义的音频捕获信息\\n    };\\n\\n    // 创建音频捕获器实例\\n    AudioCapturerManager.audioCapturer = await audio.createAudioCapturer(audioCapturerOptions);\\n\\n    // 返回创建的音频捕获器实例\\n    return AudioCapturerManager.audioCapturer;\\n  }\\n\\n  // 静态异步方法，用于启动录音过程\\n  static async startRecord(fileName: string) {\\n    await AudioCapturerManager.createAudioCapturer()\\n    // 记录开始录音的时间戳\\n    AudioCapturerManager.startRecordTime = Date.now();\\n    try {\\n      // 初始化缓冲区大小\\n      let bufferSize: number = 0;\\n\\n      // 定义一个内部类来设置写入文件时的选项\\n      class Options {\\n        offset?: number; // 文件写入位置偏移量\\n        length?: number; // 写入数据的长度\\n      }\\n\\n      // 获取应用的文件目录路径\\n      let path = getContext().filesDir;\\n\\n      // 设置录音文件的完整路径\\n      let filePath = `${path}/${fileName}.wav`;\\n      AudioCapturerManager.recordFilePath = filePath;\\n\\n      // 打开或创建录音文件\\n      let file = fs.openSync(filePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);\\n\\n      // 定义一个读取数据的回调函数\\n      let readDataCallback = (buffer: ArrayBuffer) => {\\n        // 创建一个写入文件的选项对象\\n        let options: Options = {\\n          offset: bufferSize, // 文件当前位置偏移量\\n          length: buffer.byteLength // 数据长度\\n        };\\n        // 将数据写入文件\\n        fs.writeSync(file.fd, buffer, options);\\n        // 更新缓冲区大小\\n        bufferSize += buffer.byteLength;\\n      };\\n\\n      // 给音频捕获器实例注册读取数据的事件监听器\\n      AudioCapturerManager.audioCapturer?.on(\'readData\', readDataCallback);\\n\\n      // 开始录音\\n      AudioCapturerManager.audioCapturer?.start();\\n\\n      // 返回录音文件的路径\\n      return filePath;\\n    } catch (e) {\\n      // 如果出现异常，返回空字符串\\n      return \\"\\";\\n    }\\n  }\\n\\n  // 静态异步方法，用于停止录音过程\\n  static async stopRecord() {\\n    // 停止音频捕获器的工作\\n    await AudioCapturerManager.audioCapturer?.stop();\\n    // 释放音频捕获器的资源\\n    await AudioCapturerManager.audioCapturer?.release();\\n    // 清除音频捕获器实例\\n    AudioCapturerManager.audioCapturer = null;\\n    // 记录结束录音的时间戳\\n    AudioCapturerManager.endRecordTime = Date.now();\\n\\n    // 创建并返回一个包含录音文件信息的对象\\n    const recordFile: RecordFile = {\\n      recordFilePath: AudioCapturerManager.recordFilePath,\\n      startRecordTime: AudioCapturerManager.startRecordTime,\\n      endRecordTime: AudioCapturerManager.endRecordTime,\\n    };\\n\\n    // 返回记录文件信息\\n    return recordFile;\\n  }\\n}\\n```\\n\\n## “按住说话” 发送录音\\n\\n![PixPin_2024-09-09_20-54-27](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/PixPin_2024-09-09_20-54-27.gif)\\n\\n---\\n\\n![output](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/output-1725888739673.png)\\n\\n\\n\\n> 这里我们先实现最简单的录音功能，转换文本或者取消发送下一个环节再实现\\n\\n1. 当长按 **按住说话时**，便开始**录音**\\n2. 当直接松开手指时，便**停止录音**\\n3. 同时构造声音消息，显示在聊天面板上\\n\\n### 定义全局录音文件名\\n\\n```typescript\\n  // 录音文件名称\\n  recordFileName: string = \\"\\"\\n```\\n\\n### 首页中定义开始录音的方法\\n\\n```typescript\\n// 开始录音\\nonStartRecord = () => {\\n  // 文件名  唯一\\n  this.recordFileName = Date.now().toString()\\n  AudioCapturerManager.startRecord(this.recordFileName)\\n}\\n```\\n\\n### 长按 \\"按住说话\\"，开始**录音**\\n\\n![image-20240909214010076](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909214010076.png)\\n\\n\\n\\n### 声明停止录音方法\\n\\n```typescript\\n  // 结束录音\\n  stopRecord = async () => {\\n    // res 记录录音文件的路径、时长等信息  这里返回是为了实现 发送录音消息\\n    const res = await AudioCapturerManager.stopRecord()\\n    return res\\n  }\\n```\\n\\n\\n\\n### 松开手指停止录音\\n\\n在 **onPressTalk** 中的松开手指事件  **TouchType.Up**中停止录音\\n\\n![image-20240909214836639](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909214836639.png)\\n\\n### 声明发送声音消息的方法\\n\\n![image-20240909214913820](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909214913820.png)\\n\\n\\n\\n```typescript\\n// 生成声音消息\\npostVoice = (res: RecordFile) => {\\n  // 录音时长  录音结束时间-开始录音时间\\n  const duration = Math.ceil((res.endRecordTime - res.startRecordTime) / 1000)\\n  //   生成消息文件\\n  const voiceChat = new ChatMessage(MessageType.voice, res.recordFilePath, duration)\\n  //   插入到消息数组中\\n  this.chatList.push(voiceChat)\\n}\\n```\\n\\n### 定义渲染声音消息的自定义构建函数\\n\\n![image-20240909215957894](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909215957894.png)\\n\\n该部分代码 可以根据声音消息的时长，动态设置消息的宽度\\n\\n实现的思路为：\\n\\n1. 如果 80 + 时长*3  大于屏幕的一半，那么最大就是屏幕的一半\\n2. 否则 宽度就是 80+时长*3\\n\\n```typescript\\n  \\n   .width(\\n  80 + duration * 3 > px2vp(display.getDefaultDisplaySync().width / 2) ?\\n  px2vp(display.getDefaultDisplaySync().width / 2) :\\n  80 + duration * 3\\n          )\\n```\\n```typescript\\n/**\\n * 声音消息 结构\\n * @param fileName 录音的路径-后续做点击播放使用\\n * @param time 发送消息的时间 如 22:21\\n * @param duration 消息的时长 如 5s\\n * @param index 该消息在数组中的索引 后续做声音转文本使用\\n */\\n@Builder\\nchatVoiceBuilder(fileName: string, time: string, duration: number, index: number) {\\n  Column({ space: 5 }) {\\n    Text(time)\\n      .width(\\"100%\\")\\n      .textAlign(TextAlign.Center)\\n      .fontColor(\\"#666\\")\\n      .fontSize(14)\\n    Row() {\\n      Flex({ justifyContent: FlexAlign.End }) {\\n        Column({ space: 10 }) {\\n          Row() {\\n            // 声音时长\\n            Text(`${duration}\\"`)\\n              .padding(11)\\n            Image($r(\\"app.media.voice\\"))\\n              .width(20)\\n              .rotate({\\n                angle: 180\\n              })\\n              .margin({ right: 12 })\\n            Text()\\n              .width(10)\\n              .height(10)\\n              .backgroundColor(\\"#93EC6C\\")\\n              .position({\\n                right: 0,\\n                top: 15\\n              })\\n              .translate({\\n                x: 5,\\n              })\\n              .rotate({\\n                angle: 45\\n              });\\n          }\\n          .backgroundColor(\\"#93EC6C\\")\\n          .margin({ right: 15 })\\n          .borderRadius(5)\\n          // 根据声音时长，动态计算声音长度\\n          // 如果 80 + 时长*3  大于屏幕的一半，那么最大就是屏幕的一半\\n          // 否则 宽度就是 80+时长*3\\n          .width(80 + duration * 3 > px2vp(display.getDefaultDisplaySync().width / 2) ?\\n          px2vp(display.getDefaultDisplaySync().width / 2) : 80 + duration * 3)\\n          .justifyContent(FlexAlign.End)\\n        }\\n        .alignItems(HorizontalAlign.End)\\n\\n        Image($r(\\"app.media.avatar\\"))\\n          .width(40)\\n          .aspectRatio(1)\\n      }\\n      .width(\\"100%\\")\\n      .padding({\\n        left: 40\\n      })\\n    }\\n  }\\n  .width(\\"100%\\")\\n}\\n```\\n\\n### 遍历消息数组时，动态渲染文本消息和声音消息\\n\\n![image-20240909220252656](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909220252656.png)\\n\\n```typescript\\n    if (item.type === MessageType.text) {\\n      this.chatTextBuilder(item.content, item.time)\\n    } else if (item.type === MessageType.voice) {\\n      this.chatVoiceBuilder(item.content, item.time, item.duration!, index)\\n    }\\n```\\n\\n### 松开手指停止录音 同时发送声音消息\\n\\n![image-20240909220457099](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909220457099.png)\\n\\n\\n\\n### 最后效果\\n\\n![PixPin_2024-09-09_22-04-01](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/PixPin_2024-09-09_22-04-01.gif)\\n\\n### 录音生成的文件\\n\\n生成的录音文件都放在这里了 `/data/app/el2/100/base/com.example.你项目的包名/haps/entry/files`\\n\\n![image-20240909222855321](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909222855321.png)\\n\\n\\n\\n## “按住说话” 取消发送\\n\\n![PixPin_2024-09-09_22-36-51](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/PixPin_2024-09-09_22-36-51.gif)\\n\\n该功能主要的实现流程是：\\n\\n当长按 **“按住说话”** ，并且判断手指是否移动到了 **X**（*这个功能在上一章已经实现了*），如果是，则什么都不做即可\\n\\n![image-20240909224315034](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909224315034.png)\\n\\n\\n\\n\\n\\n## 播放声音消息 AudioRendererManager\\n\\nAudioRenderer是音频渲染器，用于播放PCM（Pulse Code Modulation）音频数据，相比[AVPlayer](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/using-avplayer-for-playback-V5)而言，可以在输入前添加数据预处\\n\\n理，更适合有音频开发经验的开发者，以实现更灵活的播放功能。\\n\\n![output](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/output-1725893267840.png)\\n\\n## 封装声音播放类\\n\\n根据上述的AudioRenderer流程图，我们将封装**AudioRendererManager**声音播放类，实现了核心的五个功能：\\n\\n1. 初始化**AudioRenderer**实例\\n\\n2. 开始播放声音\\n\\n   当播放完毕时，会自动停止播放和释放资源\\n\\n3. 暂停播放声音\\n\\n4. 停止播放声音\\n\\n5. 释放AudioRenderer相关资源\\n\\n\\n\\n`\\\\entry\\\\src\\\\main\\\\ets\\\\utils\\\\AudioRendererManager.ets`\\n\\n```typescript\\nimport { audio } from \'@kit.AudioKit\';\\nimport { fileIo } from \'@kit.CoreFileKit\';\\n\\n\\nclass Options {\\n  offset?: number;\\n  length?: number;\\n}\\n\\n\\nclass AudioRendererManager {\\n  /**\\n   * 音频播放实例\\n   */\\n  private static audioRender: audio.AudioRenderer | null = null\\n\\n  /**\\n   * 初始化\\n   */\\n  static async init(fileName: string) {\\n\\n    try {\\n      let bufferSize: number = 0;\\n      let audioStreamInfo: audio.AudioStreamInfo = {\\n        samplingRate: audio.AudioSamplingRate.SAMPLE_RATE_16000, // 采样率\\n        channels: audio.AudioChannel.CHANNEL_1, // 通道\\n        sampleFormat: audio.AudioSampleFormat.SAMPLE_FORMAT_S16LE, // 采样格式\\n        encodingType: audio.AudioEncodingType.ENCODING_TYPE_RAW // 编码格式\\n      }\\n      let audioRendererInfo: audio.AudioRendererInfo = {\\n        usage: audio.StreamUsage.STREAM_USAGE_MUSIC, // 音频流使用类型\\n        rendererFlags: 0 // 音频渲染器标志\\n      }\\n      let audioRendererOptions: audio.AudioRendererOptions = {\\n        streamInfo: audioStreamInfo,\\n        rendererInfo: audioRendererInfo\\n      }\\n      let path = getContext().filesDir;\\n      // let filePath = `${path}/${fileName}.wav`;\\n      let file: fileIo.File = fileIo.openSync(fileName, fileIo.OpenMode.READ_ONLY);\\n      const fileSize = fileIo.statSync(file.path).size\\n      let writeDataCallback = (buffer: ArrayBuffer) => {\\n        let options: Options = {\\n          offset: bufferSize,\\n          length: buffer.byteLength\\n        }\\n        fileIo.readSync(file.fd, buffer, options);\\n        bufferSize += buffer.byteLength;\\n        //   自动停止\\n        if (bufferSize >= fileSize) {\\n          AudioRendererManager.stop()\\n            .then(() => {\\n              AudioRendererManager.release()\\n            })\\n        }\\n      }\\n      AudioRendererManager.audioRender = await audio.createAudioRenderer(audioRendererOptions)\\n      AudioRendererManager.audioRender.on(\\"writeData\\", writeDataCallback)\\n    } catch (e) {\\n      console.log(\\"e\\", e.message, e.code)\\n    }\\n  }\\n\\n  /** 播放 */\\n  static async start() {\\n    // 当且仅当状态为prepared、paused和stopped之一时才能启动渲染\\n    await AudioRendererManager.audioRender?.start();\\n  }\\n\\n  /** 暂停播放*/\\n  static async pause() {\\n    await AudioRendererManager.audioRender?.pause()\\n  }\\n\\n  /** 结束播放 */\\n  static async stop() {\\n    await AudioRendererManager.audioRender?.stop()\\n  }\\n\\n  /** 释放资源 */\\n  static async release() {\\n    await AudioRendererManager.audioRender?.release()\\n  }\\n}\\n\\nexport default AudioRendererManager\\n```\\n\\n## 点击声音消息，播放声音\\n\\n![image-20240909230235647](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909230235647.png)\\n\\n### 声明播放录音的函数\\n\\n```typescript\\n  // 播放聊天记录中的录音\\n  startPlayRecord = async (fileName: string) => {\\n    // console.log(\\"fileName\\",fileName)\\n    //   1 播放录音的实例的初始化\\n    await AudioRendererManager.init(fileName)\\n    //   2 播放录音\\n    AudioRendererManager.start()\\n  }\\n```\\n\\n### 给声音消息注册点击事件\\n\\n事件触发了调用播放语音的方式 `startPlayRecord`\\n\\n![image-20240909225939158](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909225939158.png)\\n\\n\\n\\n\\n\\n## 实时语音转文本\\n\\nCore Speech Kit（基础语音服务）集成了语音类基础AI能力，包括文本转语音（TextToSpeech）及语音识别（SpeechRecognizer）能力，便于用户与设备进行互动，实现将实时输入的语音与文本之间相互转换\\n\\n实时语音识别将一段音频信息（短语音模式不超过60s，长语音模式不超过8h）转换为文本。\\n\\n![output](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/output-1725894264657.png)\\n\\n## 封装语音识别类\\n\\n根据以上步骤，我们可以将语音识别拆分成核心功能：\\n\\n1. 创建语音识别引擎 `createEngine`\\n2. 设置监听的回调 `setListener`\\n3. 开始监听 `startListening`\\n4. 取消识别 `cancel`\\n5. 结束识别 `finish`\\n6. 释放资源 `shutDown`\\n\\n其中针对实际业务，利用上述功能额外组合封装了两个方法\\n\\n1. 停止并且释放资源 `release`\\n2. 一键开启识别  `init`\\n\\n`\\\\entry\\\\src\\\\main\\\\ets\\\\utils\\\\SpeechRecognizerManager.ets`\\n\\n```typescript\\nimport { speechRecognizer } from \'@kit.CoreSpeechKit\';\\nimport { fileIo } from \'@kit.CoreFileKit\';\\n\\n\\nclass SpeechRecognizerManager {\\n  /**\\n   * 语种信息\\n   * 语音模式：长\\n   */\\n  private static extraParam: Record<string, Object> = { \\"locate\\": \\"CN\\", \\"recognizerMode\\": \\"long\\" };\\n  private static initParamsInfo: speechRecognizer.CreateEngineParams = {\\n    /**\\n     * 地区信息\\n     * */\\n    language: \'zh-CN\',\\n    /**\\n     * 离线模式：1\\n     */\\n    online: 1,\\n    extraParams: this.extraParam\\n  };\\n  /**\\n   * 引擎\\n   */\\n  private static asrEngine: speechRecognizer.SpeechRecognitionEngine | null = null\\n  /**\\n   * 录音结果\\n   */\\n  static speechResult: speechRecognizer.SpeechRecognitionResult | null = null\\n  /**\\n   * 会话ID\\n   */\\n  private static sessionId: string = \\"asr\\" + Date.now()\\n\\n  /**\\n   * 创建引擎\\n   */\\n  private static async createEngine() {\\n    // 设置创建引擎参数\\n    SpeechRecognizerManager.asrEngine = await speechRecognizer.createEngine(SpeechRecognizerManager.initParamsInfo)\\n  }\\n\\n  /**\\n   * 设置回调\\n   */\\n  private static setListener(callback: (srr: speechRecognizer.SpeechRecognitionResult) => void = () => {\\n  }) {\\n    // 创建回调对象\\n    let setListener: speechRecognizer.RecognitionListener = {\\n      // 开始识别成功回调\\n      onStart(sessionId: string, eventMessage: string) {\\n      },\\n      // 事件回调\\n      onEvent(sessionId: string, eventCode: number, eventMessage: string) {\\n      },\\n      // 识别结果回调，包括中间结果和最终结果\\n      onResult(sessionId: string, result: speechRecognizer.SpeechRecognitionResult) {\\n        SpeechRecognizerManager.speechResult = result\\n        callback && callback(result)\\n      },\\n      // 识别完成回调\\n      onComplete(sessionId: string, eventMessage: string) {\\n      },\\n      // 错误回调，错误码通过本方法返回\\n      // 如：返回错误码1002200006，识别引擎正忙，引擎正在识别中\\n      // 更多错误码请参考错误码参考\\n      onError(sessionId: string, errorCode: number, errorMessage: string) {\\n      },\\n    }\\n    // 设置回调\\n    SpeechRecognizerManager.asrEngine?.setListener(setListener);\\n  }\\n\\n  /**\\n   * 开始监听\\n   * */\\n  static startListening() {\\n    // 设置开始识别的相关参数\\n    let recognizerParams: speechRecognizer.StartParams = {\\n      // 会话id\\n      sessionId: SpeechRecognizerManager.sessionId,\\n      // 音频配置信息。\\n      audioInfo: {\\n        // 音频类型。 当前仅支持“pcm”\\n        audioType: \'pcm\',\\n        // 音频的采样率。 当前仅支持16000采样率\\n        sampleRate: 16000,\\n        // 音频返回的通道数信息。 当前仅支持通道1。\\n        soundChannel: 1,\\n        // 音频返回的采样位数。 当前仅支持16位\\n        sampleBit: 16\\n      },\\n      //   录音识别\\n      extraParams: {\\n        // 0 实时录音识别\\n        \\"recognitionMode\\": 0,\\n        //   最大支持音频时长\\n        maxAudioDuration: 60000\\n      }\\n    }\\n    // 调用开始识别方法\\n    SpeechRecognizerManager.asrEngine?.startListening(recognizerParams);\\n  };\\n\\n  /**\\n   * 取消识别\\n   */\\n  static cancel() {\\n    SpeechRecognizerManager.asrEngine?.cancel(SpeechRecognizerManager.sessionId)\\n  }\\n\\n  /**\\n   * 结束识别\\n   */\\n  static finish() {\\n    SpeechRecognizerManager.asrEngine?.finish(SpeechRecognizerManager.sessionId)\\n  }\\n\\n  /**\\n   * 释放ai语音转文字引擎\\n   */\\n  static shutDown() {\\n    SpeechRecognizerManager.asrEngine?.shutdown()\\n  }\\n\\n  /**\\n   * 停止并且释放资源\\n   */\\n  static async release() {\\n    SpeechRecognizerManager.cancel()\\n    SpeechRecognizerManager.shutDown()\\n\\n  }\\n\\n  /**\\n   * 初始化ai语音转文字引擎 实现一键开启语音识别\\n   */\\n  static async init(callback: (srr: speechRecognizer.SpeechRecognitionResult) => void = () => {\\n  }) {\\n    await SpeechRecognizerManager.createEngine()\\n    SpeechRecognizerManager.setListener(callback)\\n    SpeechRecognizerManager.startListening()\\n  }\\n}\\n\\nexport default SpeechRecognizerManager\\n```\\n\\n## 语音识别业务流程\\n\\n![image-20240909232140090](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909232140090.png)\\n\\n从上可以看到，我们要做的流程是：\\n\\n1. 在开始 **按住说话** 时，也直接开启实时语音识别\\n2. 当手指移向 **文** 时，显示实时识别的文字\\n3. 如果这个时候松开手，那么发送的是文字而不是语音\\n\\n\\n\\n## ”按住说话“ 语音识别\\n\\n![PixPin_2024-09-09_23-56-16](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/PixPin_2024-09-09_23-56-16.gif)\\n\\n### 声明语音识别的文字状态\\n\\n```typescript\\n// 语音识别的文字\\n@State\\nvoiceToText: string = \\"\\"\\n```\\n\\n### 声明语音识别函数\\n\\n```typescript\\n// 开启ai实时转换声音\\nonStartSpeechRecognize = () => {\\n  // 如果你是完整的一句话，我把它拼接到 this.voiceToText 如果不是，实时显示\\n  // 缓存一段句子的变量\\n  let sentence = \\"\\"\\n  SpeechRecognizerManager.init((res) => {\\n    // console.log(\\"res\\", JSON.stringify(res))\\n    //   isFinal  这一句话 你结束了没有\\n    //   isLast 这一段语音你结束了没有\\n    // this.voiceToText = res.result\\n    if (res.isFinal) {\\n      sentence += res.result\\n      this.voiceToText = sentence\\n    } else {\\n      this.voiceToText = sentence + res.result\\n    }\\n\\n  })\\n}\\n```\\n\\n### 设置转换的文字显示在绿色容器内\\n\\n![image-20240909234345836](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909234345836.png)\\n\\n\\n\\n\\n\\n\\n\\n---\\n\\n在**talkContainerBuilder**内进行修改\\n\\n![image-20240909234518121](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909234518121.png)\\n\\n### 按住说话 开始语音识别监听\\n\\n![image-20240909234304591](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909234304591.png)\\n\\n### 松开手 结束语音识别\\n\\n![image-20240909234703000](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909234703000.png)\\n\\n### 松开手  发送文字消息\\n\\n本来是发送录音消息的，但是由于用户进行了语音转文字，所以此时直接松开手，便将语音转成的文字发送成**文字消息**\\n\\n**定义发送文字消息的方法**\\n\\n```typescript\\n// 生成文字消息\\npostText = () => {\\n  //   生成消息文件\\n  const TextChat = new ChatMessage(MessageType.text, this.voiceToText)\\n  //   插入到消息数组中\\n  this.chatList.push(TextChat)\\n}\\n```\\n\\n**松开手  发送文字消息**\\n\\n![image-20240909235517058](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909235517058.png)\\n\\n\\n\\n\\n\\n## 松开手 取消发送\\n\\n![PixPin_2024-09-10_00-00-11](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/PixPin_2024-09-10_00-00-11.gif)\\n\\n松开手时，一共有三种状态\\n\\n1. 直接发送语音\\n2. 语音识别，发送文字\\n3. 取消发送\\n\\n现在来实现最后的  松开手，取消发送功能\\n\\n![image-20240909235855966](HarmonyNext%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A902-%E5%8A%9F%E8%83%BD%E4%BA%A4%E4%BA%92.assets/image-20240909235855966.png)\\n\\n\\n\\n\\n\\n\\n\\n## 总结\\n\\n至此，该案例的功能已经全部完成\\n\\n- [x] 页面沉浸式\\n- [x] 聊天内容滚动\\n- [x] 输入框状态切换\\n- [x] 聊天信息框宽度自适应\\n- [x] 输入法避让\\n- [x] canvas声纹 按住说话 \\n- [x] 发送文字\\n- [x] 录音-发送语音\\n- [x] 语音消息根据时长自动宽度\\n- [x] 手势坐标检测取消发送-语音转文字 \\n- [x] 声音播放-语音消息\\n- [x] AI 语音转文字\\n\\n\\n\\n致自己，夜幕低垂，万籁俱寂，愿这份灵感之光伴随入梦，在未来的日子里，继续照亮探索之旅。感谢陪伴\\n\\n\\n\\n## 源码地址\\n\\nhttps://gitee.com/ukSir/hmchat2\\n\\n## 参考链接\\n\\n"}'),w={name:"鸿蒙开发技巧/HarmonyOS Next 微信聊天/带你实现HarmonyOS Next 微信聊天02/带你实现HarmonyOS Next 微信聊天02.md"};function N(z,s,O,L,H,U){return l(),e("div",null,[...s[0]||(s[0]=[p("",149)])])}const K=n(w,[["render",N]]);export{$ as __pageData,K as default};
